#include "dual_projection_sorted.cuh"
#include <random>
#include <numeric>
#include <cstdio>
int main(){try{using namespace tao::dual;std::mt19937 rng(8191);size_t checks=0;for(int cols:{3,128,256,512,1024}){int rows=8;Vec w(rows*cols);for(auto&v:w)v=float(int(rng()%33)-16)/16;for(int i=0;i<cols;++i)w[i]=0;Device W(w),Q(w.size()),S(rows);project_sorted(W,Q,S,rows,cols);auto q=Q.host(),sc=S.host();for(int r=0;r<rows;++r){std::vector<int>ids(cols);std::iota(ids.begin(),ids.end(),0);std::sort(ids.begin(),ids.end(),[&](int a,int b){float x=std::abs(w[r*cols+a]),y=std::abs(w[r*cols+b]);return x>y||(x==y&&a<b);});float sum=0,best=-1,alpha=1;int count=0;for(int i=0;i<cols;++i){sum+=std::abs(w[r*cols+ids[i]]);float score=sum*sum/(i+1);if(score>best){best=score;count=i+1;alpha=sum/count;}}if(best==0)alpha=1;if(sc[r]!=alpha)throw std::runtime_error("scale");for(int i=0;i<cols;++i){int j=ids[i];float v=w[r*cols+j],expected=i<count&&v!=0?std::copysign(alpha,v):0;if(q[r*cols+j]!=expected)throw std::runtime_error("symbol");++checks;}}}printf("PASS sorted_projection symbols=%zu ties/zero/padding and approved widths\n",checks);return 0;}catch(const std::exception&e){printf("FAIL %s\n",e.what());return 1;}}
